(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;if(root)root.MeihaoWalletAdapter=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
'use strict';
const FUNDS=Object.freeze(['snack','general','allowance']),ALLOWED=Object.freeze({snack_food:['snack','allowance'],non_food:['snack','general','allowance']}),INCOME=new Set(['initial_funding','income','scoreboard_snack','refund']);
function assert(ok,msg){if(!ok)throw new Error(msg);}
function positive(v,label){const n=Number(v);assert(Number.isSafeInteger(n)&&n>0,label+'必須是正整數。');return n;}
function dateToIso(v){assert(/^\d{4}-\d{2}-\d{2}$/.test(String(v||'')),'日期格式錯誤。');const d=new Date(v+'T12:00:00');assert(!Number.isNaN(d.getTime())&&d.getFullYear()===Number(v.slice(0,4))&&d.getMonth()+1===Number(v.slice(5,7))&&d.getDate()===Number(v.slice(8,10)),'日期無效。');return d.toISOString();}
function buildOperation(i){const type=String(i.type||''),amount=positive(i.amount,'交易金額'),note=String(i.note||'').trim();assert(note.length>0,'請填寫交易備註。');const entries=[];let category=null;
if(type==='income'||type==='initial_funding')entries.push({fundType:'allowance',delta:amount});
else if(type==='expense'){category=String(i.category||'');assert(Object.prototype.hasOwnProperty.call(ALLOWED,category),'請選擇有效的商品分類。');const a=i.allocations||{};let total=0;FUNDS.forEach(f=>{const n=Number(a[f]||0);assert(Number.isSafeInteger(n)&&n>=0,'資金分配必須是非負整數。');if(n>0){assert(ALLOWED[category].includes(f),f+'不可用於此商品分類。');entries.push({fundType:f,delta:-n});total+=n;}});assert(entries.length>0,'請至少選擇一種扣款資金。');assert(total===amount,'各資金扣款分配總額必須等於交易金額。');}
else throw new Error('此畫面僅支援初始建帳、現金收入及一般支出。');
return {type,amount,entries,category,note,occurredAt:dateToIso(i.date),idempotencyKey:String(i.idempotencyKey||'')};}
function normalizeWalletData(accounts,transactions,entries,events){const balances={snack:0,general:0,allowance:0};(accounts||[]).forEach(r=>{if(FUNDS.includes(r.fund_type))balances[r.fund_type]=Number(r.balance||0);});const byTx=new Map();(entries||[]).forEach(r=>{const a=byTx.get(r.transaction_id)||[];a.push({fundType:r.fund_type,delta:Number(r.amount_delta),balanceBefore:Number(r.balance_before),balanceAfter:Number(r.balance_after)});byTx.set(r.transaction_id,a);});const latest=new Map();(events||[]).forEach(e=>{const old=latest.get(e.targetTransactionId);if(!old||Number(e.correctionNo)>Number(old.correctionNo))latest.set(e.targetTransactionId,e);});
const rows=(transactions||[]).map(tx=>{const event=latest.get(tx.id),snap=event&&event.afterSnapshot?event.afterSnapshot:{},original=byTx.get(tx.id)||[],allocations=snap.fundAllocations||snap.fund_allocations||original.reduce((o,e)=>{o[e.fundType]=e.delta;return o;},{});return {id:tx.id,type:tx.transaction_type,amount:Number(snap.amount==null?tx.amount:snap.amount),category:snap.category==null?tx.category:snap.category,note:snap.note==null?tx.note:snap.note,occurredAt:snap.occurredAt||snap.occurred_at||tx.occurred_at,sourceType:tx.source_type,sourceId:tx.source_id,reversalOf:tx.reversal_of,entries:original,allocations,correctionEvent:event||null};}).sort((a,b)=>String(b.occurredAt).localeCompare(String(a.occurredAt)));
return {balances,totalAssets:FUNDS.reduce((n,k)=>n+balances[k],0),transactions:rows};}
function summarize(w,now){const d=now instanceof Date?now:new Date(now||Date.now()),month=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');let income=0,expense=0;(w.transactions||[]).forEach(t=>{if(!String(t.occurredAt||'').startsWith(month))return;if(INCOME.has(t.type))income+=Number(t.amount||0);if(t.type==='expense')expense+=Number(t.amount||0);});return {totalAssets:Number(w.totalAssets||0),income,expense,monthKey:month};}
return Object.freeze({FUND_TYPES:FUNDS,ALLOWED_FUNDS:ALLOWED,buildOperation,normalizeWalletData,summarize,dateToIso});});